package com.example.demo; import com.example.demo.model.User; import com.example.demo.repository.UserRepository; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.data.domain.*; @SpringBootTest class UserPaginationTest { @Autowired UserRepository r; @Test void test(){r.deleteAll(); r.save(new User("Ananya Sen","ananya@aditya.edu.in"));r.save(new User("Bhavana Reddy","bhavana@aditya.edu.in"));r.save(new User("Deepak Verma","deepak@aditya.edu.in"));r.save(new User("Rahul Kumar","rahul@aditya.edu.in"));r.save(new User("Vijay Sharma","vijay@aditya.edu.in")); Page<User> page=r.findAll(PageRequest.of(0,3,Sort.by("name").ascending())); System.out.println("[PAGINATION] Total Elements found in H2 Store: "+page.getTotalElements()); System.out.println("[PAGINATION] Total Pages compiled via segment metrics: "+page.getTotalPages()); page.getContent().forEach(u->System.out.println(" -> Name: "+u.getName()+" | Email: "+u.getEmail()));} }